// next/scripts/vite-plugin-assets.mjs
//
// Serves binary assets (audio + images) from parent repo folders during
// development, and copies them into `dist/` at build time.
//
// Assets served:
//   ../audio/*.{mp3,wav,m4a,ogg}                    → /audio/*
//   ../audio/daily/lesson-XX/*.mp3                  → /audio/daily/lesson-XX/*
//   ../source/daily/lesson-XX/images/*              → /source/daily/lesson-XX/images/*
//
// This keeps `file` and `localFile` paths generated by preprocess.mjs identical
// to what vanilla build.mjs produced, so components consume them as-is.

import { createReadStream, existsSync, statSync, cpSync, readdirSync } from "node:fs"
import { join, dirname, extname, normalize, sep } from "node:path"
import { fileURLToPath } from "node:url"

const HERE = dirname(fileURLToPath(import.meta.url))
const NEXT_ROOT = dirname(HERE)
const REPO_ROOT = dirname(NEXT_ROOT)

const MIME = {
  ".mp3": "audio/mpeg",
  ".m4a": "audio/mp4",
  ".wav": "audio/wav",
  ".ogg": "audio/ogg",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
}

// Allowed URL prefixes we will serve from disk.
const ALLOWED_PREFIXES = ["/audio/", "/source/daily/"]

function resolveAsset(pathname) {
  let decoded
  try {
    decoded = decodeURIComponent(pathname)
  } catch {
    return null
  }
  if (!ALLOWED_PREFIXES.some((p) => decoded.startsWith(p))) return null
  // Only allow known media/image extensions.
  const ext = extname(decoded).toLowerCase()
  if (!MIME[ext]) return null
  // Extra guard for source/: only /source/daily/*/images/ is exposed.
  if (decoded.startsWith("/source/daily/") && !/\/images\//.test(decoded)) return null

  const rel = decoded.replace(/^\//, "")
  const abs = normalize(join(REPO_ROOT, rel))
  // Prevent path traversal — resolved path must stay inside REPO_ROOT.
  if (!abs.startsWith(REPO_ROOT + sep) && abs !== REPO_ROOT) return null
  return abs
}

export function assetsPlugin() {
  return {
    name: "ielts-assets",
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if (!req.url) return next()
        const url = req.url.split("?")[0]
        const resolved = resolveAsset(url)
        if (!resolved) return next()
        if (!existsSync(resolved)) {
          res.statusCode = 404
          res.end("Not found: " + url)
          return
        }
        const ext = extname(resolved).toLowerCase()
        const mime = MIME[ext] || "application/octet-stream"
        const stat = statSync(resolved)
        res.setHeader("Content-Type", mime)
        res.setHeader("Content-Length", String(stat.size))
        res.setHeader("Accept-Ranges", "bytes")
        res.setHeader("Cache-Control", "public, max-age=3600")
        createReadStream(resolved).pipe(res)
      })
    },
    writeBundle(options) {
      const distDir = options.dir || join(NEXT_ROOT, "dist")
      // Copy entire audio/ tree (root notes audio + daily lessons).
      const audioSrc = join(REPO_ROOT, "audio")
      const audioDest = join(distDir, "audio")
      if (existsSync(audioSrc)) {
        cpSync(audioSrc, audioDest, { recursive: true })
      }
      // Copy source/daily/*/images → dist/source/daily/*/images
      const dailyRoot = join(REPO_ROOT, "source", "daily")
      if (existsSync(dailyRoot)) {
        for (const lesson of readdirSync(dailyRoot)) {
          const imagesSrc = join(dailyRoot, lesson, "images")
          if (!existsSync(imagesSrc)) continue
          const imagesDest = join(distDir, "source", "daily", lesson, "images")
          cpSync(imagesSrc, imagesDest, { recursive: true })
        }
      }
      console.log("[assets-plugin] Copied audio + images into dist/")
    },
  }
}
